const chatId = String($('Telegram Trigger').first().json.message.chat.id);
const collected = $('Collect jobs').first().json;
const openRoles = collected.roles || [];
const jobs = collected.jobs || [];

const WEIGHTS = { skills: 0.45, experience: 0.25, education: 0.15, additional: 0.15 };
const STRONG = 70;
const POSSIBLE = 45;
const MAX_SUGGESTIONS = 3;

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const canon = new Map(openRoles.map(r => [norm(r), r]));
const clamp = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(100, Math.max(0, Math.round(n))) : null;
};
const arr = a => (Array.isArray(a) ? a.map(String).filter(Boolean) : []);
const bullets = a => arr(a).map(x => '• ' + x).join('\n');
const statusOf = s => (s >= STRONG ? 'Strong Match' : s >= POSSIBLE ? 'Possible Match' : 'Not a Match');

const textFrom = (ai) => {
  if (ai == null) return '';
  if (typeof ai === 'string') return ai;
  const out = ai.output;
  if (typeof out === 'string') return out;
  if (out && !Array.isArray(out) && typeof out === 'object') return out;
  if (Array.isArray(out)) {
    const parts = [];
    for (const item of out) {
      for (const c of (item.content || [])) if (typeof c.text === 'string') parts.push(c.text);
      if (typeof item.text === 'string') parts.push(item.text);
    }
    if (parts.length) return parts.join('');
  }
  if (ai.matches) return ai;
  return ai.text ?? ai.message?.content ?? ai.choices?.[0]?.message?.content
      ?? ai.content?.[0]?.text ?? '';
};

const parseJson = (v) => {
  if (v && typeof v === 'object') return v;
  const s = String(v).replace(/```json|```/gi, '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a === -1 || b <= a) throw new Error('No JSON found in AI reply');
  return JSON.parse(s.slice(a, b + 1));
};

const findRole = (name) => {
  const n = norm(name);
  if (!n) return null;
  if (canon.has(n)) return canon.get(n);
  for (const [k, v] of canon) if (k.includes(n) || n.includes(k)) return v;
  return null;
};

let parseFailed = false, parseError = '', aiRoles = [], matches = [];
try {
  const raw = parseJson(textFrom($input.first().json));
  aiRoles = (raw.matches || []).map(m => m.role);

  matches = (raw.matches || []).map(m => {
    const role = findRole(m.role);
    if (!role) return null;
    const parts = {
      skills: clamp(m.skills), experience: clamp(m.experience),
      education: clamp(m.education), additional: clamp(m.additional)
    };
    let sum = 0, w = 0;
    for (const k of Object.keys(WEIGHTS)) {
      if (parts[k] !== null) { sum += parts[k] * WEIGHTS[k]; w += WEIGHTS[k]; }
    }
    if (w === 0) return null;
    const score = Math.round(sum / w);
    return { role, score, status: statusOf(score), ...parts,
             reason: m.reason || '', strengths: arr(m.strengths), gaps: arr(m.gaps) };
  }).filter(Boolean).sort((a, b) => b.score - a.score);
} catch (e) {
  parseFailed = true;
  parseError = String(e.message || e);
}

const eligible = matches.filter(m => m.score >= POSSIBLE).slice(0, MAX_SUGGESTIONS);
const best = eligible[0] || null;
const closest = matches[0] || null;
const line = (label, v) => (v === null ? null : `${label}: ${v}/100`);

let text, outcome;

if (openRoles.length === 0) {
  outcome = 'no_open_roles';
  text = ['Thank you for sharing your CV.', '',
    'There are no open positions advertised right now. Please check back soon, and send /start when new roles are posted.'].join('\n');

} else if (parseFailed || matches.length === 0) {
  outcome = 'error';
  text = ['Sorry, we could not process your CV just now.', '',
    'Please send it again in a moment. If it keeps failing, try a text-based PDF.'].join('\n');

} else if (best) {
  outcome = 'suggested';
  const header = best.status === 'Strong Match' ? 'Strong match' : 'Possible match';
  const closing = best.status === 'Strong Match'
    ? 'Great news! Your profile fits this role well, and you are eligible to proceed with your application.'
    : 'You meet part of the requirements. You can still apply, and strengthening the areas below would improve your chances.';
  text = [
    `Best role for you: ${best.role}`, '',
    `${header}  (${best.score}/100)`, '',
    ...[line('Skills', best.skills), line('Experience', best.experience),
        line('Education', best.education), line('Other requirements', best.additional)].filter(Boolean),
    '', best.reason,
    ...(best.strengths.length ? ['', 'Strengths:', bullets(best.strengths)] : []),
    ...(best.gaps.length ? ['', 'Areas to improve:', bullets(best.gaps)] : []),
    ...(eligible.length > 1
      ? ['', 'Other roles you could consider:',
         ...eligible.slice(1).map(m => `• ${m.role} (${m.score}/100, ${m.status})`)]
      : []),
    '', closing, '',
    `To apply, visit the CVscreen app, select ${best.role} role, upload your CV and apply. Type /start to scan your improved CV.`
  ].join('\n');

} else {
  outcome = 'not_qualified';
  text = [
    'Thank you for your interest.', '',
    'We could not match your CV to any of our current openings.',
    ...(closest ? ['', `Closest role: ${closest.role} (${closest.score}/100)`,
        ...(closest.gaps.length ? ['', 'To strengthen your profile for roles like this:', bullets(closest.gaps)] : [])] : []),
    '',
    'Please wait until a position that matches your skills and experience is advertised, then send /start to try again.'
  ].join('\n');
}

const bestJobId = jobs.find(j => j.title === best?.role)?.id ?? null;

return [{
  json: {
    chatId,
    text: text.slice(0, 4000),
    outcome,
    status: best?.status ?? 'Not a Match',
    bestRole: best?.role ?? null,
    bestScore: best?.score ?? null,
    bestJobId,
    skillMatch: best?.skills ?? null,
    experienceMatch: best?.experience ?? null,
    educationMatch: best?.education ?? null,
    additionalMatch: best?.additional ?? null,
    summary: best?.reason ?? '',
    strengths: best?.strengths ?? [],
    weaknesses: best?.gaps ?? [],
    debug: { parseFailed, parseError, aiRoles, openRoles, matched: matches.length }
  }
}];

