let r = $input.first().json;
r = r.message?.content ?? r.output?.[0]?.content?.[0]?.text ?? r.output ?? r;
if (typeof r === 'string') r = JSON.parse(r.replace(/```json|```/g, '').trim());

return [{ json: {
  name: r.name || '',
  email: r.email || '',
  summary: r.summary || '',
  skills: r.skills || [],
  education: r.education || [],
  experience: r.experience || [],
  certifications: r.certifications || []
}}];

// Handles both one-item-per-row and a single item holding an array
const rows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);

const seen = new Set();
const jobs = rows
  .filter(j => j.title && String(j.status || 'active').toLowerCase() === 'active')
  .map(j => ({
    id: j.id,
    title: String(j.title).trim(),
    skills: j.skills || 'Not specified',
    experience_level: j.experience_level || 'Not specified',
    education_level: j.education_level || 'Not specified',
    additional: j.additional_requirements || 'None'
  }))
  .filter(j => !seen.has(j.title) && seen.add(j.title));   // drop duplicate titles

const jobsText = jobs.map((j, i) =>
`${i + 1}. ${j.title}
   Required skills: ${j.skills}
   Experience level: ${j.experience_level}
   Education: ${j.education_level}
   Other requirements: ${j.additional}`
).join('\n\n');

return [{ json: { roles: jobs.map(j => j.title), jobs, jobsText } }];
